300	function checkDtypeSupported(m, topo){
301	  const gpu = topo.gpu || CONFIG.GPUS["H200"];
302	  if (m.weight_dtype === "nvfp4" && !gpu.supports_nvfp4)
303	    throw new Error(`NVFP4 weights require native FP4; ${gpu.name} has none`);
304	  // GPU-coupled KV dtype (GLM-5.3-Flash): fp8 KV is Blackwell-only — the
305	  // BF16-KV arm (withKvDtype "fp16", which stamps kv_dtype) must be priced
306	  // on Hopper instead (mirrors Python's check_dtype_supported)
307	  if (m.kv_fp8_blackwell_only === true && m.kv_dtype !== "fp16"
308	      && !gpu.supports_nvfp4)
309	    throw new Error(`${m.name}: FP8 KV is Blackwell-only — price the BF16-KV arm on ${gpu.name}`);
310	  // GPU-coupled FP8 row (GLM-5.3): the base constants are the Blackwell row,
311	  // so a Hopper topology needs withGpu's swap and a swapped model may price
312	  // Hopper only (mirrors Python's check_dtype_supported)
313	  if (m.kv_hopper_fp8 && m.kv_dtype !== "fp16"){
314	    const hopperRow = !!m.kv_gpu && !CONFIG.GPUS[m.kv_gpu].supports_nvfp4;
315	    if (hopperRow !== !gpu.supports_nvfp4)
316	      throw new Error(`${m.name}: its FP8 cache row depends on the GPU — price withGpu(m, "${gpu.name}") on this topology`);
317	  }
318	}
