320	// KV pool of ONE replica group. A group owns topo.tp GPUs: the weights are
321	// sharded across them and counted once, the reserve is scratch and charged per
322	// GPU -> pool = tp*(vram - reserve) - weights. Per-GROUP, i.e. per-cache; a
323	// dp>1 deployment has topo.replicas of them. A model too large for its group
324	// still clamps to 0 (the study's "does not fit" sentinel); minTpFor() reports
325	// the group size that would fit.
326	export function kv_pool_tokens(m, topo){
327	  checkDtypeSupported(m, topo);
328	  const gpu = topo.gpu || CONFIG.GPUS["H200"];
329	  const R = ACT_RESERVE + (gpu.reserve_extra || 0);
330	  // NOT factored as tp*(vram - R) - w: the three terms in this order make every
331	  // pre-existing configuration bit-identical to the pre-grid code (and to
332	  // Python's kv_pool_tokens), rather than merely equal after formatting.
333	  const poolBytes = topo.tp * gpu.vram - hbmWeights(m) - topo.tp * R;
334	  // ...in tokens of the cache the group STORES: a replicated layout pays
335	  // kv_bpt x copies per token (kvReplication) — mirrors _replicated()
336	  return Math.max(poolBytes, 0) / replicated(m, topo).kv_bpt;
337	}
