339	// KV sharding under TP (mirrors kv_replication / dcp_size / _replicated in
340	// workingset.model; research/kv_tp_sharding.md). A cache with h shardable
341	// heads splits across min(tp, h) ranks and is REPLICATED on the tp/h rank
342	// groups beyond that. topo.kv_shard "dcp" (the default — decode context
343	// parallelism, --decode-context-parallel-size floor(tp/h)) splits that
344	// dimension along the sequence: ONE copy at every tp (an odd width the heads
345	// do not divide is extrapolated as sharded, as before this layout existed);
346	// "replicate" (plain --tensor-parallel-size) pays every copy, tp/h.
347	export const KV_SHARDS = ["dcp", "replicate"];
348	export function kvReplication(m, topo){
349	  const factor = heads => {
350	    if ((topo.kv_shard || "dcp") === "dcp" || heads === undefined || heads === null || topo.tp <= heads) return 1.0;
351	    return topo.tp / heads;
352	  };
353	  return [factor(m.kv_heads), factor(m.state_heads)];
354	}
355	export function dcpSize(m, topo){
356	  if ((topo.kv_shard || "dcp") !== "dcp") return 1;
357	  return Math.max(1, Math.floor(topo.tp / Math.max(1, m.kv_heads)));
358	}
359	// the model with its cache and state bytes multiplied by the copies the group
360	// holds — what the pool and the decode step pay. Applied INSIDE kv_pool_tokens,
361	// warmCapacity and decodeCurves to the caller's model; never returned to a
362	// caller, so it cannot be applied twice.
363	export function replicated(m, topo){
364	  const [rKv, rSt] = kvReplication(m, topo);
365	  const ix = m.kv_index_bpt || 0;
366	  // a single-head index cache keeps a full copy on every rank under "replicate"
367	  const rIx = ix > 0 ? (((topo.kv_shard || "dcp") === "replicate" && topo.tp > 1) ? topo.tp : 1.0) : rKv;
368	  if (rKv === 1.0 && rSt === 1.0 && rIx === 1.0) return m;
369	  return { ...m,
370	    kv_bpt: (m.kv_bpt - ix) * rKv + ix * rIx,
371	    kv_decode_bpt: (m.kv_decode_bpt === undefined || m.kv_decode_bpt === null) ? m.kv_decode_bpt : m.kv_decode_bpt * rIx,
372	    kv_decode_const: (m.kv_decode_const ?? 0) * rKv,
373	    deltanet_state: m.deltanet_state * rSt,
374	    state_step_bytes: (m.state_step_bytes === undefined || m.state_step_bytes === null) ? m.state_step_bytes : m.state_step_bytes * rSt };
375	}
