377	// Smallest TP group size with a non-empty pool on this part. Shares the single
378	// ACT_RESERVE with the kv_pool_tokens sitting next to it, so the two always
379	// agree — and, now that the low anchor is gone, so does Python's min_tp_for
380	// (the reserve no longer depends on any UI state, so JS and Python cannot
381	// diverge here at all). Pass the model from activeModel() so a +15% weight
382	// bump is reflected in the threshold the Split control reports.
383	export function minTpFor(m, gpuKey){
384	  const gpu = CONFIG.GPUS[gpuKey || "H200"];
385	  return Math.floor(hbmWeights(m) / (gpu.vram - (ACT_RESERVE + (gpu.reserve_extra || 0)))) + 1;
386	}
