388	// Why vLLM refuses this TP width for the model, or null (mirrors
389	// vllm_tp_refused in model.py). The Split control does not offer such a
390	// width. research/kv_tp_sharding.md #6.
391	export function vllmTpRefused(m, tp){
392	  const ok = m.vllm_tp || [];
393	  if (!ok.length) return `the TP sizes vLLM accepts are not recorded for ${m.name}`;
394	  return ok.includes(tp) ? null
395	    : `vLLM refuses TP${tp} for ${m.name}; it accepts ${ok.join(', ')}`;
396	}
