398	// topology for arbitrary N GPUs of a part (mirrors topology()/tp_efficiency()
399	// in scenario_model.py): TP = one engine, weights sharded, one shared cache,
400	// 0.90 bandwidth haircut per GPU-count doubling inside the node, then a steeper
401	// CROSS_DOMAIN_EFFICIENCY penalty per doubling once a TP group spans nodes.
402	export function tpEff(n, domain){
403	  // an explicit 0/negative domain is an ERROR, not a request for the default —
404	  // `domain || 8` would silently mask a non-NVLink part as an 8-GPU node while
405	  // Python's tp_efficiency raises. Only undefined/null falls back.
406	  const d = (domain === undefined || domain === null) ? 8 : domain;
407	  if (!(d >= 1) || Math.floor(d) !== d)
408	    throw new Error(`nvlink_domain must be a positive integer, got ${domain}`);
409	  if (n<=1) return 1.0;
410	  let eff = Math.pow(CONFIG.TP_EFFICIENCY, Math.log2(Math.min(n, d)));
411	  if (n > d) eff *= Math.pow(CONFIG.CROSS_DOMAIN_EFFICIENCY, Math.log2(n/d));
412	  return eff;
413	}
414	// DP x TP grid (mirrors topology_grid() in scenario_model.py). DP replicates
415	// whole GROUPS of `tp` GPUs — the only way the models that fit no single GPU
416	// (Mistral-Medium-3.5, GLM-5.3) can be data-parallel at all.
417	export function makeGrid(dp, tp, gpuKey, kvShard){
418	  // mirror topology_grid()'s validation: a silently-accepted dp=0 would build a
419	  // zero-GPU topology whose pool still reads non-empty (the pool depends on tp)
420	  for (const [label, v] of [["dp", dp], ["tp", tp]])
421	    if (!(v >= 1) || Math.floor(v) !== v)
422	      throw new Error(`${label} must be a positive integer, got ${v}`);
423	  const key = gpuKey || "H200";
424	  if (!CONFIG.GPUS[key]) throw new Error(`unknown gpu ${key}`);
425	  const shard = kvShard || "dcp";
426	  if (!KV_SHARDS.includes(shard)) throw new Error(`kv_shard must be one of ${KV_SHARDS}, got ${kvShard}`);
427	  const g = CONFIG.GPUS[key], n = dp*tp;
428	  // names match Python's topology_grid() exactly (× for x)
429	  let name = n===1 ? `1×${g.name}`
430	           : dp===1 ? `${tp}×${g.name} tensor-par`
431	           : tp===1 ? `${dp}×${g.name} data-par`
432	           : `${n}×${g.name} DP${dp}×TP${tp}`;
433	  if (shard === "replicate" && tp > 1) name += " [KV replicated]";
434	  const kind = n===1 ? "single" : dp===1 ? "tp" : tp===1 ? "dp" : "hybrid";
435	  return {name, dp, tp, n_gpu:n, kind, replicas:dp, gpu:g, kv_shard:shard};
436	}
437	// single-axis helper for the explorer's TP/DP toggle: the two grid edges
438	export function makeTopo(kind, n, gpuKey, kvShard){
439	  if (kind!=="tp" && kind!=="dp") throw new Error(`kind must be 'tp' or 'dp', got ${kind}`);
440	  return kind==="tp" ? makeGrid(1, n, gpuKey, kvShard) : makeGrid(n, 1, gpuKey, kvShard);
441	}
442	// divisors of n, ascending — the TP widths that evenly split n GPUs
443	export function divisors(n){ const d=[]; for (let i=1;i<=n;i++) if (n%i===0) d.push(i); return d; }
444	// Snap a TP width to a legal one for `ngpu`: the largest divisor <= tp, so
445	// shrinking the GPU count keeps as much TP as still divides evenly rather than
446	// resetting the user to pure TP or pure DP. Always returns a divisor of ngpu.
447	// accepted: the model's vllm_tp, when given; widths outside it are dropped
448	export function clampTp(tp, ngpu, accepted){
449	  const ds = divisors(ngpu).filter(d => !accepted || accepted.includes(d));
450	  return ds.includes(tp) ? tp : (ds.filter(d => d <= tp).pop() ?? 1);
451	}
452	// Bandwidth seen by ONE replica group. DP adds groups, it never widens one.
453	export function effective_bw(topo){
454	  const gpu = topo.gpu || CONFIG.GPUS["H200"];
455	  return topo.tp * gpu.hbm_bw * tpEff(topo.tp, gpu.nvlink_domain);
456	}
